// ✅ Patrón correcto: separación de responsabilidades
public class MovementLogic        // POCO — lógica de movimiento pura
{
    public Vector3 ComputeVelocity(Vector3 input, float speed) =>
        input.normalized * speed;
}

public class CombatSystem         // POCO — lógica de combate pura
{
    private DamageCalculator _dmg = new DamageCalculator(15);
    public int Attack(int raw, bool crit) => _dmg.Calculate(raw, crit);
}

public class PlayerFacade : MonoBehaviour  // Fachada liviana
{
    private MovementLogic _movement = new MovementLogic();
    private CombatSystem _combat = new CombatSystem();
    private Rigidbody _rb;

    void Start() => _rb = GetComponent<Rigidbody>();

    void Update()
    {
        Vector3 input = new Vector3(Input.GetAxis("Horizontal"), 0,
                                    Input.GetAxis("Vertical"));
        _rb.velocity = _movement.ComputeVelocity(input, 5f);
    }
}

