public class EnemyFacade : MonoBehaviour
{
    private DamageSystem _damage = new DamageSystem();
    private MovementAI _ai = new MovementAI();

    void OnCollisionEnter(Collision col)
    {
        if (col.gameObject.CompareTag("Bullet"))
            _damage.ApplyDamage(10);
    }

    void Update()
    {
        _ai.UpdatePath(transform.position);
    }
}

public class EnemyShooter : MonoBehaviour
{
    private WeaponLogic _weapon = new WeaponLogic();
    private TargetingSystem _targeting = new TargetingSystem();
    private ReloadHandler _reload = new ReloadHandler();

    void Update()
    {
        if (_targeting.HasTarget())
            _weapon.Fire(_targeting.GetTarget());

        if (_weapon.NeedsReload())
            _reload.Reload(_weapon);
    }
}

